# Ecom Code Connect Mappings

**Owner:** figma-synth
**Scope:** Canonical Code Connect templates for common ecom components. Reuse across builds.

## Component library

### ProductCard
```tsx
import { figma } from "@figma/code-connect"
import { ProductCard } from "@/components/product-card"

figma.connect(ProductCard, "FIGMA_NODE_URL", {
  props: {
    title: figma.string("Title"),
    price: figma.string("Price"),
    compareAtPrice: figma.string("Compare At Price"),
    image: figma.instance("Image"),
    badge: figma.enum("Badge", {
      "None": undefined,
      "Sale": "sale",
      "New": "new",
      "Bestseller": "bestseller",
    }),
    soldOut: figma.boolean("Sold Out"),
  },
  example: (props) => <ProductCard {...props} />,
})
```

### VariantSelector
```tsx
figma.connect(VariantSelector, "URL", {
  props: {
    type: figma.enum("Type", {
      "Color Swatch": "color",
      "Size Button": "size",
      "Bundle Picker": "bundle",
    }),
    options: figma.string("Options"),
    selected: figma.string("Selected"),
  },
  example: ({ type, options }) => (
    <VariantSelector type={type} options={options.split(",")} />
  ),
})
```

### AddToCartCTA
```tsx
figma.connect(AddToCartCTA, "URL", {
  props: {
    label: figma.string("Label"),
    variant: figma.enum("Variant", {
      "Primary": "primary",
      "Sticky Bottom": "sticky-bottom",
    }),
    loading: figma.boolean("Loading"),
    disabled: figma.boolean("Disabled"),
  },
  example: (props) => <AddToCartCTA {...props} />,
})
```

### CartDrawer
```tsx
figma.connect(CartDrawer, "URL", {
  props: {
    open: figma.boolean("Open"),
    items: figma.children("Items"),
    showFreeShipping: figma.boolean("Show Free Shipping"),
    showUpsell: figma.boolean("Show Upsell"),
  },
  example: (props) => <CartDrawer {...props} />,
})
```

### CartLineItem
```tsx
figma.connect(CartLineItem, "URL", {
  props: {
    title: figma.string("Title"),
    variant: figma.string("Variant Detail"),
    price: figma.string("Price"),
    quantity: figma.string("Quantity"),
    image: figma.instance("Image"),
  },
  example: (props) => <CartLineItem {...props} />,
})
```

### CheckoutStep
```tsx
figma.connect(CheckoutStep, "URL", {
  props: {
    step: figma.enum("Step", {
      "Email": "email",
      "Shipping": "shipping",
      "Payment": "payment",
      "Review": "review",
    }),
    state: figma.enum("State", {
      "Active": "active",
      "Complete": "complete",
      "Pending": "pending",
    }),
  },
  example: (props) => <CheckoutStep {...props} />,
})
```

### TrustBadge
```tsx
figma.connect(TrustBadge, "URL", {
  props: {
    type: figma.enum("Type", {
      "Free Shipping": "shipping",
      "Returns": "returns",
      "Secure Checkout": "secure",
      "Sustainability": "sustainability",
    }),
    label: figma.string("Label"),
  },
  example: (props) => <TrustBadge {...props} />,
})
```

### PriceBlock
```tsx
figma.connect(PriceBlock, "URL", {
  props: {
    price: figma.string("Price"),
    compareAtPrice: figma.string("Compare At"),
    showSubscriptionToggle: figma.boolean("Show Subscription"),
  },
  example: (props) => <PriceBlock {...props} />,
})
```

### ReviewStars
```tsx
figma.connect(ReviewStars, "URL", {
  props: {
    rating: figma.string("Rating"),
    reviewCount: figma.string("Review Count"),
    size: figma.enum("Size", { "Small": "sm", "Medium": "md", "Large": "lg" }),
  },
  example: (props) => <ReviewStars {...props} />,
})
```

### SubscriptionToggle
```tsx
figma.connect(SubscriptionToggle, "URL", {
  props: {
    selected: figma.enum("Selected", { "One Time": "one-time", "Subscribe": "subscribe" }),
    discountPct: figma.string("Discount %"),
  },
  example: (props) => <SubscriptionToggle {...props} />,
})
```

## Reuse protocol
- New ecom build: copy these templates to project's `components/*.figma.tsx`
- Update FIGMA_NODE_URL per project
- Add project-specific variants if needed
- Register all via `send_code_connect_mappings`

## Maintenance
- This file updated whenever a canonical ecom component evolves
- Cross-reference with elio's surface library for component coverage

